  "a_sentences": [
    {
      "a_text": "Die Versicherte bestreitet, dass die Vorinstanz Bundesrecht verletzte, indem sie die Ablehnung des Leistungsgesuchs mit Verfügung vom 12. September 2023 bestätigte (P1).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Das Bundesgericht wendet die Bestimmungen und Grundsätze zur Invalidität (Art. 8 ATSG), zum Anspruch auf eine Invalidenrente (Art. 28 IVG) sowie zur Anspruchsprüfung bei einer Neuanmeldung nach vorausgegangener Ablehnung des Rentenanspruchs unter analoger Anwendung der Grundsätze zur Rentenrevision nach Art. 17 ATSG an (P2).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Auf ein versicherungsexternes Gutachten ist praxisgemäss abzustellen, sofern nicht konkrete Indizien gegen dessen Zuverlässigkeit sprechen (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Ein strukturiertes Beweisverfahren bleibt entbehrlich, wenn im Rahmen beweiswertiger fachärztlicher Berichte eine Arbeitsunfähigkeit nachvollziehbar verneint wird und gegenteiligen Einschätzungen mangels fachärztlicher Qualifikation oder aus anderen Gründen kein Beweiswert zukommt (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Die Vorinstanz hat die Einwände gegen das ZIMB-Gutachten entkräftet und keine Verletzung der Beweiswürdigungsregeln begangen (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Das Abstellen der Vorinstanz auf das ZIMB-Gutachten vom 14. November 2022 ist nicht zu beanstanden (P6).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Eine EMRK-Verletzung wird nicht begründet, weshalb das Bundesgericht darauf nicht eintritt (P7).",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Das Bundesgericht erachtet die Beschwerde als unbegründet und bestätigt die vorinstanzliche Verfügung (P8).",
      "b_propositions": ["P8"]
    }
  ]
}
